CREATE DATABASE IF NOT EXISTS mms_boutique CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mms_boutique;

CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('owner','manager') NOT NULL DEFAULT 'owner', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (`key` VARCHAR(100) PRIMARY KEY, `value` TEXT NULL);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description TEXT, price DECIMAL(10,2) NOT NULL, compare_price DECIMAL(10,2) NULL, stock INT NOT NULL DEFAULT 0, sizes VARCHAR(255) NULL, colors VARCHAR(255) NULL, image VARCHAR(255) NULL, active TINYINT(1) DEFAULT 1, featured TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE posts (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, body TEXT NOT NULL, image VARCHAR(255) NULL, published TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE testimonials (id INT AUTO_INCREMENT PRIMARY KEY, author VARCHAR(120) NOT NULL, location VARCHAR(120), content TEXT NOT NULL, active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(160) NOT NULL, customer_email VARCHAR(190) NOT NULL, customer_phone VARCHAR(40), address TEXT, total DECIMAL(10,2) NOT NULL, status ENUM('pending','paid','processing','shipped','completed','cancelled') DEFAULT 'pending', payment_method ENUM('pix','card','cash') DEFAULT 'pix', payment_reference VARCHAR(190) NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT NULL, product_name VARCHAR(180) NOT NULL, size VARCHAR(50), color VARCHAR(80), quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE messages (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190), phone VARCHAR(40), subject VARCHAR(180), message TEXT NOT NULL, status ENUM('new','read','replied','archived') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(160) NOT NULL, order_id INT NULL, metadata TEXT NULL, ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES admins(id) ON DELETE SET NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL);

